전문가를 위한 C
목록 보기
1/1
Chapter 1. 필수 요소
1.1 전처리기 지시자
C/C++에서는 컴파일러로 소스 코드가 전달되기 전 전처리(preprocessing) 과정을 거친다. C 전처리기는 #로 시작하는 지시자(directive)를 제거하고 C 코드에 의해 생성된 동일한 내용으로 변환한 후 해당 코드를 컴파일러로 전달한다.
1.1.1 매크로
매크로는 다음과 같이 활용된다.
상수 정의
C 함수 정의 없이 함수 사용
루프 풀기(loop unrolling)
헤더 가드(header guard)
코드 생성
조건부 컴파일
매크로 정의하기
#define 지시자로 정의하며, 각 매크로는 이름과 매개변수(parameter) 리스트, 값(value)을 갖는다. 값은 매크로 확장 단계를 통해 전처리 단계에서 매크로 이름으로 대체될 수 있다. #undef 지시자로는 매크로의 정의를 제거할 수 있다.
코드 박스 1-1 [예제 1-1] 매크로 정의하기
#define ABC 5
int main(int argc, char** argv) {
int x = 2;
int y = ABC;
int z = x + y;
return 0;
}
코드 박스 1-2 매크로 확장 단계 이후 [예제 1-1]에서 생성된 코드
int main(int argc, char** argv) {
int x = 2;
int y = 5;
int z = x + y;
return 0;
}
전처리 결과 매크로가 제거되면서 값으로 치환된다.
코드 박스 1-3 [예제 1-2] 유사 함수 매크로 정의하기
#define ADD(a, b) (a + b)
int main(int argc, char** argv) {
int x = 2;
int y = 3;
int z = ADD(x, y);
return 0;
}
코드 박스 1-4 전처리와 매크로 확장 이후 코드
int main(int argc, char** argv) {
int x = 2;
int y = 3;
int z = (x + y);
return 0;
}
ADD는 함수가 아닌 인수(argument)를 전달받는 유사 함수 매크로(function-like macro)이다. 매크로는 컴파일 전 코드를 생성(generate)할 수 있도록 하며, 다른 프로그래밍 언어에서는 이를 위해 코드 생성기(code generator)가 필요하다.
그러나 현대 C 컴파일러는 전처리 단계에 대해 인지하고 있으며 C 전처리기 지시자가 포함된 전처리 단계 이전의 소스 코드를 알고 있다.
코드 박스 1-5 선언되지 않은 식별자 오류가 발생하는 매크로 정의
#include <stdio.h>
#define CODE \
printf("%d\n", i);
int main(int argc, char** argv) {
CODE
return 0;
}
셀 박스 1-1 매크로 정의를 나타내는 컴파일 출력
$ clang example.c
example.c:7:5: error: use of undeclared identifier 'i'
7 | CODE
| ^~~~
example.c:4:16: note: expanded from macro 'CODE'
4 | printf("%d\n", i);
| ^
1 error generated.
변환 단위(translation unit) 또는 컴파일 단위(compilation unit)란 전처리된 C 코드이다. 모든 지시자가 포함(inclusion)되거나 매크로 확장으로 대체되며 단 한 줄의 긴 C 코드가 생성된다.
코드 박스 1-6 [예제 1-3] 루프를 생성하는 매크로 사용하기
#include <stdio.h>
#define PRINT(a) printf("%d\n", a);
#define LOOP(v, s, e) for (int v = s; v <= e; ++v) {
#define ENDLOOP }
int main(int argc, char** argv) {
LOOP(counter, 1, 10)
PRINT(counter)
ENDLOOP
return 0;
}
코드 박스 1-7 전처리 단계 이후의 [예제 1-3]
...
... content of stdio.h ...
...
int main(int argc, char** argv) {
for (int counter = 1; counter <= 10; ++counter) {
printf("%d\n", counter);
}
return 0;
}
위와 같이 매크로를 활용해 그 자체로는 C의 문법이 아니지만 전처리 이후 C의 문법을 준수하도록 할 수 있다. 이는 도메인 특화 언어(DSL: Domain Specific Language)를 정의할 때 사용되는 매크로 활용법이다.
코드 박스 1-8 [예제 1-4] 매크로에서 #과 ## 연산자 사용하기
#include <stdio.h>
#include <string.h>
#define CMD(NAME) \
char NAME ## _cmd[256] = ""; \
strcpy(NAME ## _cmd, #NAME);
int main(int argc, char** argv) {
CMD(copy)
CMD(paste)
CMD(cut)
char cmd[256];
scanf("%s", cmd);
if (strcmp(cmd, copy_cmd) == 0) {
// ...
}
if (strcmp(cmd, paste_cmd) == 0) {
// ...
}
if (strcmp(cmd, cut_cmd) == 0) {
// ...
}
return 0;
}
코드 박스 1-9 전처리 단계 이후의 [예제 1-4]
...
... content of stdio.h ...
...
... content of string.h ...
...
int main(int argc, char** argv) {
char copy_cmd[256] = ""; strcpy(copy_cmd, "copy");
char paste_cmd[256] = ""; strcpy(paste_cmd, "paste");
char cut_cmd[256] = ""; strcpy(cut_cmd, "cut");
char cmd[256];
scanf("%s", cmd);
if (strcmp(cmd, copy_cmd) == 0) {
}
if (strcmp(cmd, paste_cmd) == 0) {
}
if (strcmp(cmd, cut_cmd) == 0) {
}
return 0;
}
매크로 확장 시 # 연산자는 매개변수를 한 쌍의 따옴표로 둘러싼 문자로 변환하고, ## 연산자는 매크로의 매개변수와 다른 요소를 문자열로 결합해 변수 이름을 생성한다.
가변 인자 매크로
가변 인자 매크로(variable macro)는 가변 인수(variable argument)를 받을 수 있다.
코드 박스 1-10 [예제 1-5] 가변 인자 매크로의 정의와 사용
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define VERSION "2.3.4"
#define LOG_ERROR(format, ...) \
fprintf(stderr, format, __VA_ARGS__)
int main(int argc, char** argv) {
if (argc < 3) {
LOG_ERROR("Invalid number of arguments for version %s\n", VERSION);
exit(1);
}
if (strcmp(argv[1], "-n") != 0) {
LOG_ERROR("%s is a wrong param at index %d for version %s.", argv[1], 1, VERSION);
exit(1);
}
// ...
return 0;
}
코드 박스 1-11 전처리 단계 이후의 [예제 1-5]
...
... content of stdio.h ...
...
... content of stdlib.h ...
...
... content of string.h ...
...
int main(int argc, char** argv) {
if (argc < 3) {
fprintf(stderr, "Invalid number of arguments for version %s\n.", "2.3.4");
exit(1);
}
if (strcmp(argv[1], "-n") != 0) {
fprintf(stderr, "%s is a wrong param at index %d for version %s.", argv[1], 1, "2.3.4");
exit(1);
}
// ...
return 0;
전처리기는 __VA_ARGS__ 식별자를 아직 매개변수에 할당되지 않은 나머지 모든 입력 인수로 교체한다.
코드 박스 1-12 [예제 1-6] 루프를 모방한 가변 인자 매크로 사용하기
#include <stdio.h>
#define LOOP_3(X, ...) \
printf("%s\n", #X);
#define LOOP_2(X, ...) \
printf("%s\n", #X); \
LOOP_3(__VA_ARGS__)
#define LOOP_1(X, ...) \
printf("%s\n", #X); \
LOOP_2(__VA_ARGS__)
#define LOOP(...) \
LOOP_1(__VA_ARGS__)
int main(int argc, char** argv) {
LOOP(copy paste cut)
LOOP(copy, paste, cut)
LOOP(copy, paste, cut, select)
return 0;
}
코드 박스 1-13 전처리 단계 이후의 [예제 1-6]
...
... content of stdio.h ...
...
int main(int argc, char** argv) {
printf("%s\n", "copy paste cut"); printf("%s\n", ""); printf("%s\n", "");
printf("%s\n", "copy"); printf("%s\n", "paste"); printf("%s\n", "cut");
printf("%s\n", "copy"); printf("%s\n", "paste"); printf("%s\n", "cut");
return 0;
}
매크로로는 직접적인 루프를 만들 수 없고, 루프 풀기(loop unrolling)를 통해 개별 명령어를 반복적으로 삽입하는 우회적인 방법만 존재한다. 이로 인해 이진 파일의 크기는 증가하지만 제한적인 환경에서 고성능을 낼 수 있다.
매크로의 장점과 단점
매크로의 장점
1. 루프 풀기 등의 방법으로 성능을 향상시킬 수 있다.
전처리된 코드 형태의 영향을 잘 알고 있다면 단점이 상쇄된다.
매크로의 단점
1. 컴파일 결과 모듈성(modularity)을 갖지 않는 한 줄로 된 코드가 생성된다.
과거 C 컴파일러의 경우 컴파일 경고(compilation warning)에 기반한 디버깅이 까다로웠다.
1.1.2 조건부 컴파일
조건부 컴파일(conditional compilation)은 상이한 조건에 기반해 전처리가 서로 다른 방식으로 수행되는 것이다. 대표적으로 다음 지시자가 사용된다.
#ifdef
#ifndef
#else
#elif
#endif
코드 박스 1-14 [예제 1-7] 조건부 컴파일 예
#define CONDITION
int main(int argc, char** argv) {
#ifdef CONDITION
int i = 0;
++i;
#endif
int j = 0;
return 0;
}
코드 박스 1-15 전처리 단계 이후의 [예제 1-7]
int main(int argc, char** argv) {
int i = 0;
++i;
int j = 0;
return 0;
}
$ gcc -DCONDITION -E main.c
gcc 컴파일 과정에서 -D 옵션을 사용해 매크로를 정의할 수 있다.
코드 박스 1-16 CONDITION 매크로가 정의되지 않았다고 가정한 전처리 단계 이후의 [예제 1-7]
int main(int argc, char** argv) {
int j = 0;
return 0;
}
#ifdef 지시자로 지정한 매크로가 정의되어 있다면 전처리 과정에서 #endif 지시자 전까지의 소스 코드가 삽입된다.
#ifndef 지시자는 전처리 단계에서 헤더 파일이 두 번 포함되는 것을 방지하기 위한 헤더 가드 구문으로 흔히 사용한다.
코드 박스 1-17 [예제 1-8] 헤더 가드의 예
#ifndef EXAMPLE_1_8_H
#define EXAMPLE_1_8_H
void say_hello();
int read_age();
#endif
처음 헤더 파일이 포함될 때 매크로가 정의되지 않았기 때문에 #ifndef~#endif 사이의 코드가 전처리되지만, 두 번째로 포함될 때부터는 이미 정의되었으므로 해당 코드는 단 한 번만 생성된다.
#pragma once 지시자도 같은 동작을 보이고 대부분의 C 전처리기가 지원하지만 C 표준이 아니기 때문에 코드의 이식성(portability) 측면에서 권장되지 않는다.
코드 박스 1-18 [예제 1-8]에서 #pragma once 사용하기
#pragma once
void say_hello();
int read_age();
1.2 포인터 변수
1.2.1 문법
코드 박스 1-19 [예제 1-8] C에서 포인터 변수를 선언하고 사용하는 방법
int main(int argc, char** argv) {
int var = 100;
int* ptr = 0;
ptr = &var;
*ptr = 200;
return 0;
}
&는 참조 연산자(reference operator), *는 역참조 연산자(dereference pointer)라 칭한다.
값이 0(NULL 매크로)인 포인터를 널 포인터(null pointer)라고 하며, 유효한 주소를 저장하지 않는 경우나 변수 선언 시 포인터를 널로 만드는 것이 중요하다. 널 포인터를 역참조하는 것은 정의되지 않은 동작이기 때문에 충돌로 이어진다.
코드 박스 1-20 포인터를 널로 만드는 NULL 매크로의 사용
char* ptr = NULL;
코드 박스 1-21 C++11에서 포인터를 널로 만드는 nullptr의 사용
char* ptr = nullptr;
1.2.2 포인터 변수의 산술연산
C 자료형(date type)에 의해 포인터 변수에 대한 증감 연산 시의 메모리 이동 간격을 의미하는 산술연산 간격(arithmetic step size)이 결정된다.
코드 박스 1-22 [예제 1-10] 두 포인터의 산술연산 간격
#include <stdio.h>
int main(int argc, char** argv) {
int var = 1;
int* int_ptr = NULL; // initialize as null pointer
int_ptr = &var;
char* char_ptr = NULL;
char_ptr = (char*)&var;
printf("Before arithmetic: int_ptr: %u, char_ptr: %u\n",
(unsigned int) int_ptr, (unsigned int) char_ptr);
++int_ptr; // arithmetic step size == 4
++char_ptr; // arithmetic step size == 1
printf("After arithmetic: int_ptr: %u, char_ptr: %u\n",
(unsigned int) int_ptr, (unsigned int) char_ptr);
return 0;
}
